import { z } from "zod";
import { unitIdSchema } from "../admissions";

const APPLICATION_DEADLINE_TYPES = [
  "ED",
  "EDII",
  "EA",
  "EAII",
  "REA",
  "RD",
  "ROLLING",
] as const;
export const applicationDeadlineTypeSchema = z.enum(APPLICATION_DEADLINE_TYPES);
export type ApplicationDeadlineType =
  (typeof APPLICATION_DEADLINE_TYPES)[number];

export const applicationDeadlineSchema = z
  .object({
    id: z.string(),
    applicationDataId: z.string(),
    type: applicationDeadlineTypeSchema,
    deadlineAt: z.string().nullable(),
    description: z.string().nullable(),
    createdAt: z.string(),
    updatedAt: z.string(),
  })
  .strict();
export type ApplicationDeadline = z.infer<typeof applicationDeadlineSchema>;

const APPLICATION_ESSAY_TYPES = [
  "COMMON_APP",
  "SUPPLEMENT",
  "PROGRAM",
] as const;
export const applicationEssayTypeSchema = z.enum(APPLICATION_ESSAY_TYPES);
export type ApplicationEssayType = (typeof APPLICATION_ESSAY_TYPES)[number];

export const applicationEssaySchema = z
  .object({
    id: z.string(),
    applicationDataId: z.string(),
    promptId: z.string().nullable(),
    type: applicationEssayTypeSchema,
    prompt: z.string(),
    required: z.boolean(),
    minWords: z.number().int().nullable(),
    maxWords: z.number().int().nullable(),
    topic: z.string().nullable(),
    sourceUrl: z.string().nullable(),
    instructions: z.string().nullable(),
    createdAt: z.string(),
    updatedAt: z.string(),
  })
  .strict();
export type ApplicationEssay = z.infer<typeof applicationEssaySchema>;

export const applicationDataSchema = z
  .object({
    id: z.string(),
    unitid: unitIdSchema,
    memberId: z.string().nullable(),
    cycleLabel: z.string(),
    deadlines: z.array(applicationDeadlineSchema).default([]),
    essays: z.array(applicationEssaySchema).default([]),
    createdAt: z.string(),
    updatedAt: z.string(),
  })
  .strict();
export type ApplicationData = z.infer<typeof applicationDataSchema>;
